using System;
using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine;
public static class LunaV007ChainAudit { public static void Run(){ EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity",OpenSceneMode.Single); var table=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); foreach(var n in new[]{"V007_VISUAL_MAIN","Yellow","Blue","Pink","Black","TABLE SURFACE","Bed_Collider"}){var t=Find(table.transform,n); if(t==null){Debug.Log("[CHAIN] MISSING "+n);continue;} Debug.Log("[CHAIN] "+n); for(var p=t;p!=null;p=p.parent) Debug.Log($"  {p.name} local={p.localPosition:F6} rot={p.localEulerAngles:F3} scale={p.localScale:F6} world={p.position:F6}");} EditorApplication.Exit(0);} static Transform Find(Transform r,string n){foreach(var t in r.GetComponentsInChildren<Transform>(true))if(t.name==n)return t;return null;} }
